// Local tsumego solver (boolean minimax with transposition table).
// Board 19x19 embedded in 21x21 with EDGE border. Index = (y+1)*21 + (x+1).
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define N 19
#define WD 21
#define SZ (WD*WD)
#define EMPTY 0
#define BLACK 1
#define WHITE 2
#define EDGE 3
#define PASSMOVE 0

static const int D4[4] = {1, -1, WD, -WD};

static uint8_t g_region[SZ], g_safe[SZ], g_target[SZ];
static int g_regionlist[SZ], g_nregion;
static int g_att, g_def, g_kowin, g_strict;
static long long g_nodes, g_maxnodes;
static int g_maxdepth = 100;
static int g_aborted, g_depthhits, g_def_has_safe;

static uint64_t zob[3][SZ], zob_side, zob_ko[SZ], zob_pass, zob_settings;

typedef struct {
    uint8_t b[SZ];
    int ko;       // point banned for side to move (0 = none)
    int lastpass; // previous move was a pass that counts toward ending the game
    uint64_t hash;
} State;

typedef struct {
    uint64_t key;
    int8_t result;
    int16_t best;
} TTEntry;

#define TTBITS 22
#define TTSIZE (1u << TTBITS)
static TTEntry *tt = NULL;

static uint64_t path[4096];
static int pathlen;

static uint64_t rng_state = 0x9E3779B97F4A7C15ULL;
static uint64_t rng(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 7;
    rng_state ^= rng_state << 17;
    return rng_state * 0x2545F4914F6CDD1DULL;
}

static int inited = 0;
static void init_zobrist(void) {
    if (inited) return;
    inited = 1;
    for (int c = 0; c < 3; c++)
        for (int p = 0; p < SZ; p++) zob[c][p] = rng();
    zob_side = rng();
    for (int p = 0; p < SZ; p++) zob_ko[p] = rng();
    zob_pass = rng();
    tt = (TTEntry *)calloc(TTSIZE, sizeof(TTEntry));
}

static int gmark[SZ], ggen = 1;
static int lmark[SZ], lgen = 1;

static int get_chain(const uint8_t *b, int p, int *out, int *nl, int *sf) {
    int c = b[p];
    int n = 0, head = 0, libs = 0, s = 0;
    ggen++;
    lgen++;
    out[n++] = p;
    gmark[p] = ggen;
    while (head < n) {
        int q = out[head++];
        if (g_safe[q]) s = 1;
        for (int d = 0; d < 4; d++) {
            int r = q + D4[d];
            if (b[r] == c) {
                if (gmark[r] != ggen) { gmark[r] = ggen; out[n++] = r; }
            } else if (b[r] == EMPTY && lmark[r] != lgen) {
                lmark[r] = lgen;
                libs++;
            }
        }
    }
    *nl = libs;
    *sf = s;
    return n;
}

// Returns 1 if legal. Sets *cap_target if a target stone was captured.
static int play(State *s, int p, int c, int *cap_target) {
    int stones[SZ];
    int nl, sf;
    *cap_target = 0;
    int o = 3 - c;
    if (s->b[p] != EMPTY || !g_region[p]) return 0;
    if (p == s->ko && c != g_kowin) return 0;
    s->b[p] = (uint8_t)c;
    s->hash ^= zob[c][p];
    int ncap = 0, lastcap = 0;
    for (int d = 0; d < 4; d++) {
        int q = p + D4[d];
        if (s->b[q] == o) {
            int n = get_chain(s->b, q, stones, &nl, &sf);
            if (nl == 0 && !sf) {
                for (int i = 0; i < n; i++) {
                    int r = stones[i];
                    if (g_target[r] && o == g_def) *cap_target = 1;
                    s->b[r] = EMPTY;
                    s->hash ^= zob[o][r];
                }
                ncap += n;
                lastcap = stones[0];
            }
        }
    }
    int n = get_chain(s->b, p, stones, &nl, &sf);
    if (nl == 0 && !sf) return 0;
    if (ncap == 1 && n == 1 && nl == 1) s->ko = lastcap; else s->ko = 0;
    s->lastpass = 0;
    return 1;
}

// Benson unconditional life for all target chains of g_def.
static int chain_id[SZ], region_id[SZ];
static int benson_targets_alive(const uint8_t *b) {
    int nch = 0, nrg = 0;
    static int stack[SZ];
    for (int p = 0; p < SZ; p++) { chain_id[p] = -1; region_id[p] = -1; }
    for (int p = 0; p < SZ; p++) {
        if (b[p] == g_def && chain_id[p] < 0) {
            int sp = 0;
            stack[sp++] = p;
            chain_id[p] = nch;
            while (sp) {
                int q = stack[--sp];
                for (int d = 0; d < 4; d++) {
                    int r = q + D4[d];
                    if (b[r] == g_def && chain_id[r] < 0) { chain_id[r] = nch; stack[sp++] = r; }
                }
            }
            nch++;
        }
    }
    if (nch == 0) return 0;
    for (int p = 0; p < SZ; p++) {
        if (b[p] != g_def && b[p] != EDGE && region_id[p] < 0) {
            int sp = 0;
            stack[sp++] = p;
            region_id[p] = nrg;
            while (sp) {
                int q = stack[--sp];
                for (int d = 0; d < 4; d++) {
                    int r = q + D4[d];
                    if (b[r] != g_def && b[r] != EDGE && region_id[r] < 0) { region_id[r] = nrg; stack[sp++] = r; }
                }
            }
            nrg++;
        }
    }
    // per region: number of empty points; per (region, chain): count of empty points adjacent to chain
    // Use small dynamic arrays.
    int *nempty = (int *)calloc(nrg, sizeof(int));
    int *cnt = (int *)calloc((size_t)nrg * nch, sizeof(int));
    uint8_t *adj = (uint8_t *)calloc((size_t)nrg * nch, 1);
    for (int p = 0; p < SZ; p++) {
        if (region_id[p] < 0) continue;
        int r = region_id[p];
        int seen[4], ns = 0;
        for (int d = 0; d < 4; d++) {
            int q = p + D4[d];
            if (b[q] == g_def) {
                int c = chain_id[q];
                adj[r * nch + c] = 1;
                int dup = 0;
                for (int k = 0; k < ns; k++) if (seen[k] == c) dup = 1;
                if (!dup) seen[ns++] = c;
            }
        }
        if (b[p] == EMPTY) {
            nempty[r]++;
            for (int k = 0; k < ns; k++) cnt[r * nch + seen[k]]++;
        }
    }
    uint8_t *alive = (uint8_t *)malloc(nch);
    uint8_t *rok = (uint8_t *)malloc(nrg);
    memset(alive, 1, nch);
    memset(rok, 1, nrg);
    int changed = 1;
    while (changed) {
        changed = 0;
        for (int r = 0; r < nrg; r++) {
            if (!rok[r]) continue;
            for (int c = 0; c < nch; c++)
                if (adj[r * nch + c] && !alive[c]) { rok[r] = 0; break; }
        }
        for (int c = 0; c < nch; c++) {
            if (!alive[c]) continue;
            int v = 0;
            for (int r = 0; r < nrg; r++)
                if (rok[r] && adj[r * nch + c] && nempty[r] > 0 && cnt[r * nch + c] == nempty[r]) v++;
            if (v < 2) { alive[c] = 0; changed = 1; }
        }
    }
    int ok = 1;
    for (int p = 0; p < SZ; p++)
        if (g_target[p] && b[p] == g_def && !alive[chain_id[p]]) { ok = 0; break; }
    free(nempty); free(cnt); free(adj); free(alive); free(rok);
    return ok;
}

static int target_connected_to_safe(const uint8_t *b) {
    if (!g_def_has_safe) return 0;
    int stones[SZ], nl, sf;
    for (int p = 0; p < SZ; p++) {
        if (g_target[p] && b[p] == g_def) {
            get_chain(b, p, stones, &nl, &sf);
            if (sf) return 1;
        }
    }
    return 0;
}

static uint64_t state_key(const State *s, int tomove) {
    uint64_t k = s->hash ^ zob_settings;
    if (tomove == WHITE) k ^= zob_side;
    k ^= zob_ko[s->ko];
    if (s->lastpass) k ^= zob_pass;
    return k;
}

static int move_score(const State *s, int p, int tomove) {
    // simple ordering heuristic
    int sc = 0;
    int stones[SZ], nl, sf;
    for (int d = 0; d < 4; d++) {
        int q = p + D4[d];
        int c = s->b[q];
        if (c == BLACK || c == WHITE) {
            sc += 2;
            get_chain(s->b, q, stones, &nl, &sf);
            if (c != tomove && !sf) {
                if (nl == 1) sc += 40;
                else if (nl == 2) sc += 10;
                if (g_target[stones[0]] || c == g_def) sc += 3;
            } else if (c == tomove) {
                if (nl == 1) sc += 30;
                else if (nl == 2) sc += 5;
            }
        } else if (c == EDGE) {
            sc -= 1;
        }
    }
    return sc;
}

static int search(State *s, int tomove, int depth, int *taint);

static int search_child(State *s, int m, int tomove, int depth, int *legal, int *ctaint) {
    // returns 1 if tomove wins by playing m
    State c = *s;
    *ctaint = 0;
    *legal = 1;
    if (m == PASSMOVE) {
        if (s->lastpass) {
            // game over
            int winner = g_strict ? (benson_targets_alive(s->b) ? g_def : g_att) : g_def;
            return winner == tomove;
        }
        c.lastpass = (s->ko == 0 || tomove == g_kowin) ? 1 : 0;
        c.ko = 0;
        int r = search(&c, 3 - tomove, depth + 1, ctaint);
        return !r;
    }
    int capt;
    if (!play(&c, m, tomove, &capt)) { *legal = 0; return 0; }
    if (capt) return tomove == g_att;
    if (tomove == g_def && target_connected_to_safe(c.b)) return 1;
    int r = search(&c, 3 - tomove, depth + 1, ctaint);
    return !r;
}

static int search(State *s, int tomove, int depth, int *taint) {
    *taint = 0;
    g_nodes++;
    if (g_maxnodes > 0 && g_nodes > g_maxnodes) { g_aborted = 1; *taint = 1; return 0; }
    if (g_aborted) { *taint = 1; return 0; }
    if (benson_targets_alive(s->b)) return tomove == g_def;
    uint64_t key = state_key(s, tomove);
    for (int i = 0; i < pathlen; i++)
        if (path[i] == key) { *taint = 1; return tomove == g_kowin; }
    TTEntry *e = &tt[key & (TTSIZE - 1)];
    int ttbest = -1;
    if (e->key == key) {
        return e->result;
    }
    if (depth >= g_maxdepth) { g_depthhits++; *taint = 1; return tomove == g_def; }

    int moves[SZ + 1], scores[SZ + 1], nm = 0;
    for (int i = 0; i < g_nregion; i++) {
        int p = g_regionlist[i];
        if (s->b[p] != EMPTY) continue;
        if (p == s->ko && tomove != g_kowin) continue;
        moves[nm] = p;
        scores[nm] = move_score(s, p, tomove);
        if (p == ttbest) scores[nm] += 1000;
        nm++;
    }
    // sort by score desc (insertion sort)
    for (int i = 1; i < nm; i++) {
        int m = moves[i], sc = scores[i], j = i - 1;
        while (j >= 0 && scores[j] < sc) { moves[j + 1] = moves[j]; scores[j + 1] = scores[j]; j--; }
        moves[j + 1] = m; scores[j + 1] = sc;
    }
    moves[nm++] = PASSMOVE;

    path[pathlen++] = key;
    int result = 0, anytaint = 0, best = -1;
    int tainted_win = 0, tainted_win_move = -1;
    for (int i = 0; i < nm; i++) {
        int legal, ct;
        int w = search_child(s, moves[i], tomove, depth, &legal, &ct);
        if (!legal) continue;
        if (g_aborted) break;
        if (w) {
            if (!ct) { result = 1; best = moves[i]; tainted_win = 0; break; }
            if (!tainted_win) { tainted_win = 1; tainted_win_move = moves[i]; }
        } else {
            if (ct) anytaint = 1;
        }
    }
    pathlen--;
    if (g_aborted) { *taint = 1; return 0; }
    if (!result && tainted_win) { result = 1; best = tainted_win_move; *taint = 1; }
    else if (!result) { *taint = anytaint; }
    if (!*taint) {
        e->key = key;
        e->result = (int8_t)result;
        e->best = (int16_t)best;
    }
    return result;
}

