N = 19
EMPTY, BLACK, WHITE = 0, 1, 2
CNAME = {BLACK: 'B', WHITE: 'W'}


def opp(c):
    return 3 - c


def sgf2i(s):
    return (ord(s[1]) - 97) * N + (ord(s[0]) - 97)


def i2sgf(i):
    return chr(97 + i % N) + chr(97 + i // N)


def i2xy(i):
    return i % N, i // N


def xy2i(x, y):
    return y * N + x


def neighbors(i):
    x, y = i % N, i // N
    if x > 0:
        yield i - 1
    if x < N - 1:
        yield i + 1
    if y > 0:
        yield i - N
    if y < N - 1:
        yield i + N


