            for i, c in stones.items():
                self.b[i] = c

    def copy(self):
        nb = Board()
        nb.b = self.b[:]
        nb.ko = self.ko
        return nb

    def chain(self, i):
        c = self.b[i]
        stones = {i}
        libs = set()
        stack = [i]
        while stack:
            p = stack.pop()
            for q in neighbors(p):
                if self.b[q] == c and q not in stones:
                    stones.add(q)
                    stack.append(q)
                elif self.b[q] == EMPTY:
                    libs.add(q)
        return stones, libs

    def play(self, i, c):
        """Play move; returns list of captured points. Raises IllegalMove."""
        if self.b[i] != EMPTY:
            raise IllegalMove('occupied %s' % i2sgf(i))
        if self.ko is not None and i == self.ko:
            raise IllegalMove('ko ban %s' % i2sgf(i))
        self.b[i] = c
        captured = []
        for q in neighbors(i):
            if self.b[q] == opp(c):
                st, lb = self.chain(q)
                if not lb:
                    for s in st:
                        self.b[s] = EMPTY
                    captured.extend(st)
        st, lb = self.chain(i)
        if not lb:
            self.b[i] = EMPTY
            for s in captured:
                self.b[s] = opp(c)
            raise IllegalMove('suicide %s' % i2sgf(i))
        if len(captured) == 1 and len(st) == 1 and len(lb) == 1:
            self.ko = captured[0]
        else:
            self.ko = None
        return captured

    def show(self, x0=0, y0=0, x1=18, y1=18, marks=None):
        marks = marks or {}
        lines = []
        cols = 'ABCDEFGHJKLMNOPQRST'
        lines.append('    ' + ' '.join(chr(97 + x) for x in range(x0, x1 + 1)))
        for y in range(y0, y1 + 1):
            row = []
            for x in range(x0, x1 + 1):
                i = xy2i(x, y)
                if i in marks:
                    row.append(marks[i])
                else:
