    for (int d = 0; d < 4; d++) {
        int q = p + D4[d];
        if (s->b[q] == o) {
            int n = get_chain(s->b, q, stones, &nl, &sf, NULL);
            if (nl == 0 && !sf) {
                for (int i = 0; i < n; i++) {
                    int r = stones[i];
                    if (g_target[r] && o == g_def) *cap_target = 1;
                    s->b[r] = EMPTY;
                    s->hash ^= zob[o][r];
                }
                ncap += n;
                lastcap = stones[0];
            }
        }
    }
    int n = get_chain(s->b, p, stones, &nl, &sf, NULL);
    if (nl == 0 && !sf) return 0;
    if (ncap == 1 && n == 1 && nl == 1) s->ko = lastcap; else s->ko = 0;
    s->lastpass = 0;
