            int v = 0;
            for (int r = 0; r < nrg; r++)
                if (b_rok[r] && b_adj[r][c] && b_nempty[r] > 0 && b_cnt[r][c] == b_nempty[r]) v++;
            if (v < 2) { b_alive[c] = 0; changed = 1; }
