"""Go helpers: board rules, SGF parse/write, ctypes bridge to C solver, tree validator."""
import ctypes
import os
import re

HERE = os.path.dirname(os.path.abspath(__file__))
N = 19
EMPTY, BLACK, WHITE = 0, 1, 2
CNAME = {BLACK: 'B', WHITE: 'W'}


def opp(c):
    return 3 - c


def sgf2i(s):
    return (ord(s[1]) - 97) * N + (ord(s[0]) - 97)


def i2sgf(i):
    return chr(97 + i % N) + chr(97 + i // N)


def i2xy(i):
    return i % N, i // N


def xy2i(x, y):
    return y * N + x


def neighbors(i):
    x, y = i % N, i // N
    if x > 0:
        yield i - 1
    if x < N - 1:
        yield i + 1
    if y > 0:
        yield i - N
    if y < N - 1:
        yield i + N


class IllegalMove(Exception):
    pass


class Board:
    def __init__(self, stones=None):
        self.b = [EMPTY] * (N * N)
        self.ko = None  # point banned for side to move
        if stones:
            for i, c in stones.items():
                self.b[i] = c

    def copy(self):
        nb = Board()
        nb.b = self.b[:]
        nb.ko = self.ko
        return nb

    def chain(self, i):
        c = self.b[i]
        stones = {i}
        libs = set()
        stack = [i]
        while stack:
            p = stack.pop()
            for q in neighbors(p):
                if self.b[q] == c and q not in stones:
                    stones.add(q)
                    stack.append(q)
                elif self.b[q] == EMPTY:
                    libs.add(q)
        return stones, libs

    def play(self, i, c):
        """Play move; returns list of captured points. Raises IllegalMove."""
        if self.b[i] != EMPTY:
            raise IllegalMove('occupied %s' % i2sgf(i))
        if self.ko is not None and i == self.ko:
            raise IllegalMove('ko ban %s' % i2sgf(i))
        self.b[i] = c
        captured = []
        for q in neighbors(i):
            if self.b[q] == opp(c):
                st, lb = self.chain(q)
                if not lb:
                    for s in st:
                        self.b[s] = EMPTY
                    captured.extend(st)
        st, lb = self.chain(i)
        if not lb:
            self.b[i] = EMPTY
            for s in captured:
                self.b[s] = opp(c)
            raise IllegalMove('suicide %s' % i2sgf(i))
        if len(captured) == 1 and len(st) == 1 and len(lb) == 1:
            self.ko = captured[0]
        else:
            self.ko = None
        return captured

    def show(self, x0=0, y0=0, x1=18, y1=18, marks=None):
        marks = marks or {}
        lines = []
        cols = 'ABCDEFGHJKLMNOPQRST'
        lines.append('    ' + ' '.join(chr(97 + x) for x in range(x0, x1 + 1)))
        for y in range(y0, y1 + 1):
            row = []
            for x in range(x0, x1 + 1):
                i = xy2i(x, y)
                if i in marks:
                    row.append(marks[i])
                else:
                    row.append({EMPTY: '.', BLACK: 'X', WHITE: 'O'}[self.b[i]])
            lines.append('%s%2d %s' % (chr(97 + y), 19 - y, ' '.join(row)))
        return '\n'.join(lines)


# ---------------------------------------------------------------- SGF
class Node:
    def __init__(self, props=None):
        self.props = props or {}
        self.children = []

    def move(self):
        for k in ('B', 'W'):
            if k in self.props:
                return (BLACK if k == 'B' else WHITE, self.props[k][0])
        return None

    def comment(self):
        return ''.join(self.props.get('C', []))


def parse_sgf(text):
    pos = 0
    text = text.strip()

    def skip_ws():
        nonlocal pos
        while pos < len(text) and text[pos] in ' \t\r\n':
            pos += 1

    def parse_value():
        nonlocal pos
        assert text[pos] == '['
        pos += 1
        out = []
        while text[pos] != ']':
            if text[pos] == '\\':
                pos += 1
            out.append(text[pos])
            pos += 1
        pos += 1
        return ''.join(out)

    def parse_node():
        nonlocal pos
        assert text[pos] == ';'
        pos += 1
        props = {}
        skip_ws()
        while pos < len(text) and text[pos].isalpha():
            m = re.match(r'[A-Za-z]+', text[pos:])
            key = m.group(0)
            pos += len(key)
            skip_ws()
            vals = []
            while pos < len(text) and text[pos] == '[':
                vals.append(parse_value())
                skip_ws()
            props.setdefault(key, []).extend(vals)
            skip_ws()
        return Node(props)

    def parse_tree():
        nonlocal pos
        skip_ws()
        assert text[pos] == '(', text[pos:pos + 20]
        pos += 1
        skip_ws()
        first = None
        cur = None
        while text[pos] == ';':
            n = parse_node()
            if first is None:
                first = n
            else:
                cur.children.append(n)
            cur = n
            skip_ws()
        while text[pos] == '(':
            sub = parse_tree()
            cur.children.append(sub)
            skip_ws()
        assert text[pos] == ')', text[pos:pos + 20]
        pos += 1
        return first

    root = parse_tree()
    skip_ws()
    assert pos == len(text), 'trailing data'
    return root


def write_sgf(root):
    def esc(v):
        return v.replace('\\', '\\\\').replace(']', '\\]')

    def node_str(n):
        s = ';'
        for k, vs in n.props.items():
            s += k + ''.join('[%s]' % esc(v) for v in vs)
        return s

    def tree_str(n):
        s = node_str(n)
        while len(n.children) == 1:
            n = n.children[0]
            s += node_str(n)
        if n.children:
            s += ''.join('(' + tree_str(c) + ')' for c in n.children)
        return s

    return '(' + tree_str(root) + ')'


