"""Essential tree: solver's winning moves + opponent replies that force unique (or 2) answers."""
import sys
from gotools import *

_cache = {}


def labels(prob, board, tomove, solver, objective, maxnodes=5_000_000):
    key = (tuple(board.b), board.ko, tomove, id(prob))
    if key in _cache:
        return _cache[key]
    res, overall, stats = classify(prob, board, tomove, solver, objective, maxnodes=maxnodes)
    if any(v == -2 for v in overall.values()):
        raise RuntimeError('abort')
    if not res and all(v in (2, 3) for v in overall.values()):
        lab = 'win' if solver != prob.attacker else 'lose'
        res = {'*alive*': lab}
    elif not res and all(v == 4 for v in overall.values()):
        lab = 'win' if solver == prob.attacker else 'lose'
        res = {'*alive*': lab}
    _cache[key] = res
    return res


def winning(res):
    return sorted(m for m, v in res.items() if v == 'win')


def after(board, m, c):
    nb = board.copy()
    if m != 'pass':
        nb.play(sgf2i(m), c)
    else:
        nb.ko = None
    return nb


def etree(prob, board, solver, objective, maxdepth=12, depth=0, crit=2, out=None, indent=''):
    """Called with solver to move. Prints essential tree."""
    res = labels(prob, board, solver, solver, objective)
    if '*alive*' in res:
        print(indent + '(already settled: %s)' % res['*alive*'])
        return
    wins = winning(res)
    if not wins:
        print(indent + 'SOLVER FAILS here')
        return
    print(indent + 'solver wins by: %s' % ' '.join(wins))
    if depth >= maxdepth:
        return
    if len(wins) > 3:
        print(indent + '  (many winning moves; settled)')
        return
    for m in wins:
        if m == 'pass':
            continue
        nb = after(board, m, solver)
        o = opp(solver)
        r2 = labels(prob, nb, o, solver, objective)
        if '*alive*' in r2:
            print(indent + '  %s%s -> settled (%s)' % (CNAME[solver], m, r2['*alive*']))
            continue
        crits = []
        for om in sorted(r2):
            if r2[om] != 'win':
                print(indent + '  %s%s: opp %s gives %s !!' % (CNAME[solver], m, om, r2[om]))
                continue
            nb2 = after(nb, om, o)
            r3 = labels(prob, nb2, solver, solver, objective)
            if '*alive*' in r3:
                continue
            w3 = winning(r3)
            if len(w3) <= crit:
                crits.append((om, w3, nb2))
        if not crits:
            print(indent + '  %s%s -> no critical replies (endpoint)' % (CNAME[solver], m))
            continue
        print(indent + '  %s%s -> critical replies: %s' % (CNAME[solver], m, ' '.join('%s[%s]' % (om, ','.join(w3)) for om, w3, _ in crits)))
        for om, w3, nb2 in crits:
            print(indent + '    %s%s %s%s:' % (CNAME[solver], m, CNAME[o], om))
            etree(prob, nb2, solver, objective, maxdepth, depth + 2, crit, out, indent + '      ')


