    import designs
    from design import load
    name = sys.argv[1]
    seq = [m for m in (sys.argv[2].split(',') if len(sys.argv) > 2 else []) if m]
    d, prob = load(name)
    b = prob.board.copy()
    c = d['first']
    for m in seq:
