"""Independent structural check of output SGFs (fresh minimal implementation)."""
import re
import sys

N = 19


def parse(text):
    assert text.startswith('(;') and text.endswith(')'), 'must start with (; and end with )'
    pos = 0

    def node():
        nonlocal pos
        assert text[pos] == ';'
        pos += 1
        props = []
        while pos < len(text) and text[pos].isupper():
            m = re.match(r'[A-Z]+', text[pos:])
            k = m.group(0)
            pos += len(k)
            vals = []
            while pos < len(text) and text[pos] == '[':
                j = pos + 1
                v = ''
                while text[j] != ']':
                    if text[j] == '\\':
                        j += 1
                    v += text[j]
                    j += 1
                vals.append(v)
                pos = j + 1
            props.append((k, vals))
        return {'props': props, 'children': []}

    def tree():
        nonlocal pos
        assert text[pos] == '('
        pos += 1
        first = cur = None
        while text[pos] == ';':
            n = node()
            if first is None:
                first = n
            else:
                cur['children'].append(n)
            cur = n
        while text[pos] == '(':
            cur['children'].append(tree())
        assert text[pos] == ')'
        pos += 1
        return first

    t = tree()
    assert pos == len(text), 'trailing data'
    return t


def xy(s):
    return ord(s[0]) - 97, ord(s[1]) - 97


def neighbors(x, y):
    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        a, b = x + dx, y + dy
        if 0 <= a < N and 0 <= b < N:
            yield a, b


def group(board, x, y):
    c = board[(x, y)]
    seen = {(x, y)}
    libs = set()
    st = [(x, y)]
    while st:
        p = st.pop()
        for q in neighbors(*p):
            v = board.get(q)
            if v == c and q not in seen:
                seen.add(q)
                st.append(q)
            elif v is None:
                libs.add(q)
    return seen, libs


def play(board, ko, x, y, c):
    if (x, y) in board:
        raise ValueError('occupied')
    if ko == (x, y):
        raise ValueError('ko')
    b = dict(board)
    b[(x, y)] = c
    o = 'W' if c == 'B' else 'B'
    caps = []
    for q in neighbors(x, y):
        if b.get(q) == o:
            g, l = group(b, *q)
            if not l:
                for s in g:
                    del b[s]
                caps += list(g)
    g, l = group(b, x, y)
    if not l:
        raise ValueError('suicide')
    newko = caps[0] if (len(caps) == 1 and len(g) == 1 and len(l) == 1) else None
